1	//! Command-line parsing matching the reference C++ behavior: the first
2	//! user-supplied argument is parsed like glibc `atoi`, defaulting to 7.
3	
4	/// Parse `n` from the first command-line argument.
5	///
6	/// Behavior matches glibc `atoi` on the first user argument:
7	/// - missing argument => 7
8	/// - leading C whitespace skipped (space, \t, \n, \v, \f, \r)
9	/// - optional '+'/'-' sign
10	/// - leading decimal digits consumed
11	/// - no digits => 0
12	/// - digit accumulation saturates to i64::MAX / i64::MIN (strtol-style)
13	/// - result cast/wrapped to i32 via `as i32`
14	///
15	/// Extra arguments are ignored.
16	pub fn parse_n() -> i32 {
17	    let arg = match std::env::args().nth(1) {
18	        Some(a) => a,
19	        None => return 7,
20	    };
21	    atoi(&arg)
22	}
