24	fn atoi(s: &str) -> i32 {
25	    let bytes = s.as_bytes();
26	    let mut i = 0;
27	
28	    // glibc isspace(): space, \t, \n, \v, \f, \r
29	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
30	        i += 1;
31	    }
32	
33	    let mut negative = false;
34	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
35	        negative = bytes[i] == b'-';
36	        i += 1;
37	    }
38	
39	    // Accumulate like strtol with long saturation (LONG_MAX / LONG_MIN).
40	    let mut value: i64 = 0;
41	    let mut overflowed = false;
42	    while i < bytes.len() && bytes[i].is_ascii_digit() {
43	        if !overflowed {
44	            let digit = (bytes[i] - b'0') as i64;
45	            match value
46	                .checked_mul(10)
47	                .and_then(|v| v.checked_add(digit))
48	            {
49	                Some(v) => value = v,
50	                None => overflowed = true,
51	            }
52	        }
53	        i += 1;
54	    }
55	
56	    if overflowed {
57	        value = i64::MAX;
58	    }
59	
60	    let result: i64 = if negative {
61	        if overflowed {
62	            // strtol returns LONG_MIN on negative overflow.
63	            i64::MIN
64	        } else {
65	            -value
66	        }
67	    } else {
68	        value
69	    };
70	
71	    result as i32
72	}

1	//! Geometry generation: spiral point sequence used as earcut input.
2	
3	use std::f64::consts::PI;
4	
5	/// Build the reference spiral of `2 * n` points.
6	///
7	/// For `i` in `0..2n`:
8	/// - `t = i as f64 / (2n) as f64`
9	/// - `radius = t`
10	/// - `angle = (4.0 * PI) * t`
11	/// - point = `(radius * cos(angle), radius * sin(angle))`
12	///
13	/// Negative or zero `n` yields an empty vector (no points).
14	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
15	    if n <= 0 {
16	        return Vec::new();
17	    }
18	    let count = n * 2;
19	    let denom = count as f64;
20	    let mut points = Vec::with_capacity(count as usize);
21	    for i in 0..count {
22	        let t = i as f64 / denom;
23	        let radius = t;
24	        let angle = (4.0 * PI) * t;
25	        points.push([radius * angle.cos(), radius * angle.sin()]);
26	    }
27	    points
28	}
